import re
import hmac
import hashlib
import time
import ipaddress
from urllib.parse import urlparse, urljoin
from flask import Flask, request, jsonify, abort
import requests

app = Flask(__name__)
app.secret_key = 'supersecretkey_for_hmac_signing'

ALLOWED_SCHEMES = {'http', 'https'}
BLOCKED_RANGES = [
    ipaddress.ip_network('127.0.0.0/8'),
    ipaddress.ip_network('10.0.0.0/8'),
    ipaddress.ip_network('172.16.0.0/12'),
    ipaddress.ip_network('192.168.0.0/16'),
    ipaddress.ip_network('169.254.0.0/16'),
    ipaddress.ip_network('::1/128'),
    ipaddress.ip_network('fc00::/7'),
]

def _generate_request_token(url, timestamp):
    """Generate HMAC token for request auditing"""
    msg = f"{url}|{timestamp}".encode('utf-8')
    return hmac.new(app.secret_key.encode(), msg, hashlib.sha256).hexdigest()

def _is_ip_blocked(hostname):
    """Check if the resolved IP is in a blocked range"""
    try:
        import socket
        resolved = socket.getaddrinfo(hostname, None)
        for family, socktype, proto, canonname, sockaddr in resolved:
            ip = ipaddress.ip_address(sockaddr[0])
            for network in BLOCKED_RANGES:
                if ip in network:
                    return True
        return False
    except (socket.gaierror, ValueError):
        return True

def _validate_url(url):
    """Validate URL scheme and host before fetching"""
    parsed = urlparse(url)
    if parsed.scheme not in ALLOWED_SCHEMES:
        return False, "Invalid scheme"
    if not parsed.hostname:
        return False, "No hostname"
    # Block requests to internal IPs
    if _is_ip_blocked(parsed.hostname):
        return False, "Blocked IP range"
    return True, None

def _validate_redirect(response, original_url):
    """Validate redirect target before following"""
    if not response.is_redirect:
        return True, None
    redirect_url = response.headers.get('Location', '')
    # Resolve relative redirects against the ORIGINAL url
    resolved_redirect = urljoin(original_url, redirect_url)
    parsed = urlparse(resolved_redirect)
    if parsed.scheme not in ALLOWED_SCHEMES:
        return False, "Redirect to invalid scheme"
    # NOTE: We validate the redirect hostname
    # But we use the response's url after following, not parsed.hostname
    return True, parsed.hostname

def _fetch_with_redirects(url, max_redirects=5):
    """Fetch URL following redirects with validation at each hop"""
    session = requests.Session()
    current_url = url
    visited = set()

    for i in range(max_redirects):
        if current_url in visited:
            return None, "Redirect loop detected"
        visited.add(current_url)

        resp = session.get(current_url, allow_redirects=False, timeout=10)

        if resp.status_code in (301, 302, 303, 307, 308):
            redirect_target = resp.headers.get('Location', '')
            resolved_target = urljoin(current_url, redirect_target)

            # Validate the redirect target
            valid, redirect_hostname = _validate_redirect(resp, current_url)
            if not valid:
                return None, "Invalid redirect"

            # BUG: validates redirect_hostname from _validate_redirect
            # but then follows resolved_target which may differ due to
            # urljoin resolving differently with the current_url base
            # vs original_url base used in _validate_redirect
            current_url = resolved_target
        else:
            return resp, None

    return None, "Too many redirects"

@app.route('/api/webhook/test', methods=['POST'])
def test_webhook():
    """Test a webhook URL by fetching it and returning status"""
    data = request.get_json()
    if not data or 'url' not in data:
        abort(400, description="Missing 'url' field")

    target_url = data['url']

    # Validate the initial URL
    valid, error = _validate_url(target_url)
    if not valid:
        return jsonify({'error': error, 'status': 'blocked'}), 403

    # Fetch with redirect following
    try:
        response, error = _fetch_with_redirects(target_url)
        if error:
            return jsonify({'error': error, 'status': 'failed'}), 400

        return jsonify({
            'status': 'success',
            'response_code': response.status_code,
            'content_length': len(response.content),
            'final_url': response.url,
            'headers': dict(response.headers)
        })
    except requests.exceptions.Timeout:
        return jsonify({'error': 'Timeout', 'status': 'failed'}), 504
    except requests.exceptions.RequestException as e:
        return jsonify({'error': str(e), 'status': 'failed'}), 502

@app.route('/api/fetch-preview', methods=['POST'])
def fetch_preview():
    """Fetch a URL preview (title, description, image)"""
    data = request.get_json()
    if not data or 'url' not in data:
        abort(400, description="Missing 'url' field")

    target_url = data['url']

    valid, error = _validate_url(target_url)
    if not valid:
        return jsonify({'error': error}), 403

    try:
        response, error = _fetch_with_redirects(target_url)
        if error:
            return jsonify({'error': error}), 400

        content = response.text[:10000]
        title_match = re.search(r'<title>(.*?)</title>', content, re.IGNORECASE | re.DOTALL)
        desc_match = re.search(r'<meta[^>]*name=["\']description["\'][^>]*content=["\']([^"\']*)["\']', content, re.IGNORECASE)

        return jsonify({
            'title': title_match.group(1) if title_match else None,
            'description': desc_match.group(1) if desc_match else None,
            'final_url': response.url
        })
    except requests.exceptions.RequestException as e:
        return jsonify({'error': str(e)}), 502

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
